CREATE TABLE `platform_audit_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NULL,`actor_id` CHAR(36) CHARACTER SET ascii NULL,`action` VARCHAR(128) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(64) CHARACTER SET ascii NOT NULL,`resource_id` VARCHAR(191) NULL,`outcome` ENUM('succeeded','failed','blocked') NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`metadata` JSON NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` SMALLINT UNSIGNED NOT NULL DEFAULT 1,PRIMARY KEY(`id`),KEY `idx_platform_audit_scope_time`(`organization_id`,`occurred_at`,`id`),KEY `idx_platform_audit_action_time`(`action`,`occurred_at`),KEY `idx_platform_audit_request`(`request_id`),KEY `idx_platform_audit_trace`(`trace_id`),CONSTRAINT `fk_platform_audit_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_audit_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_audit_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
